635				if err != nil {
636					mu.Lock()
637					errs = append(errs, err)
638					mu.Unlock()
639					return
640				}
641				r := r1
642				if i%2 == 1 {
643					r = r2
644				}
645				_, _, err = store.Submit([]Heartbeat{r}, receive)
646				mu.Lock()
647				if err == nil {
648					successes++
649				} else if strings.Contains(err.Error(), "conflict") {
650					conflicts++
651				} else {
