			// Health must refuse.
			_, err = store.Health("n1", receive, "1.0", 0)
			if err == nil || !IsCorrupt(err) {
				t.Errorf("health: expected corruption error, got %v", err)
			}
			// History must refuse.
			_, err = store.History("n1")
			if err == nil || !IsCorrupt(err) {
