// mergeRecord applies the dedup/conflict rule that both submit phases share:
// a record is identified by its node id and seq, and known must contain only
// records of that same node. If known already holds that identity, the
// incoming record is a duplicate when Heartbeat.Equal says the content is
// identical (collection time compared as an instant) and a conflict
// otherwise; conflicts are errors naming the node and seq, and nothing is
// modified. Otherwise the record is appended and returned in the updated
// slice. The returned dup reports which case applied.
func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
	for _, e := range known {
		if e.Seq == r.Seq {
			if !e.Equal(r) {
				return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs from previously seen record", r.NodeID, r.Seq)
			}
			return known, true, nil
		}
